// Calculate 24-26 hour window from now
const now = DateTime.now();
const timeMin = now.plus({ hours: 24 }).toISO();
const timeMax = now.plus({ hours: 26 }).toISO();

return [{
  json: {
    timeMin,
    timeMax,
    checkTime: now.toISO()
  }
}];

const items = $input.all();
const keywords = ['discovery', 'call', 'meeting', 'nca'];

// ── Deduplication via static data ───────────────────────
// Track processed eventIds so the same calendar event is never
// briefed twice, even if it falls inside the time-window on
// consecutive daily runs.
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedEvents) {
  staticData.processedEvents = {};
}

// Purge entries older than 30 days to prevent memory bloat
const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.processedEvents)) {
  if (now - Number(ts) > THIRTY_DAYS_MS) {
    delete staticData.processedEvents[id];
  }
}

const callEvents = items.filter(item => {
  const title = (item.json.summary || '').toLowerCase();
  return keywords.some(kw => title.includes(kw));
});

if (callEvents.length === 0) {
  return [];
}

// Filter out already-processed events
const newEvents = callEvents.filter(event => {
  const eventId = event.json.id;
  if (staticData.processedEvents[eventId]) {
    return false; // already briefed — skip
  }
  return true;
});

if (newEvents.length === 0) {
  return []; // all events already processed
}

// Extract org name and contact from attendees
const results = newEvents.map(event => {
  const attendees = event.json.attendees || [];
  const externalAttendees = attendees.filter(a => !a.organizer && !a.self);
  const contact = externalAttendees[0] || {};
  const contactName = contact.displayName || contact.email || 'Unknown Contact';
  const contactEmail = contact.email || '';

  let orgName = 'Unknown Organization';
  if (contactEmail && contactEmail.includes('@')) {
    const domain = contactEmail.split('@')[1];
    if (domain && !domain.includes('gmail') && !domain.includes('yahoo') && !domain.includes('hotmail') && !domain.includes('outlook')) {
      orgName = domain.split('.')[0].charAt(0).toUpperCase() + domain.split('.')[0].slice(1);
    }
  }

  const startTime = event.json.start?.dateTime || event.json.start?.date || '';

  // Mark as processed BEFORE returning so next run skips it
  staticData.processedEvents[event.json.id] = Date.now();

  return {
    json: {
      eventId: event.json.id,
      title: event.json.summary,
      contactName,
      contactEmail,
      orgName,
      startTime,
      calendarLink: event.json.htmlLink || ''
    }
  };
});

return results;

